/**
 * Вид у приціл: o.ret, o.mag, o.dist, o.tgt, o.mode ('range'|'aim'), o.hx, o.hy — винос в одиницях сітки на калібрувальній кратності;
 * o.zoom — лупа (1, 2, 4, 6) на точку виносу чи ціль: кільце й підпис лишаються того ж розміру на екрані.
 */
/** У скільки разів ціль на сітці менша, ніж на калібрувальній кратності: у FFP — завжди 1. */
const kOf = (C, mag) => (C.ffp ? 1 : mag / C.cal);

function scope(svg, o) {
  const C = RET[o.ret]; const R = C.ffp ? C.R * C.cal / o.mag : C.R; const k = kOf(C, o.mag); const T = TGT[o.tgt];
  svg.replaceChildren();
  const z = o.zoom > 1 ? o.zoom : 1;
  const id = `guide-clip${uid++}`;
  const cp = mk('clipPath', { id }, mk('defs', {}, svg));
  mk('circle', { cx: 0, cy: 0, r: R }, cp);
  const g = mk('g', { 'clip-path': `url(#${id})` }, svg);
  mk('rect', { x: -R, y: -R, width: 2 * R, height: 2 * R, class: 'r-sky' }, g);
  const H = C.size(T.h, o.dist) * k;
  let cx; let top;
  // Далекомір: верх цілі на горизонтальній нитці, лівий край — впритул до міток вертикалі (риски DSMR ±0,4, точки Plex ±0,55)
  if (o.mode === 'range') { cx = T.w * H / 2 + (C.u === 'MOA' ? 0.65 : 0.5); top = 0; } else { cx = o.hx * k - (T.ax ?? 0) * (o.flip ? -H : H); top = o.hy * k - T.ap * H; }
  // Лупа дивиться туди, де важливо: у прицілюванні — на точку виносу (після відповіді — щоб влізли центр, попадання й правильна точка), у далекомірі — на ціль; не виходить за коло
  // Запас під обвідку кола — пропорційний полю, інакше на малому R (EBR-2C на 16×) ціль виходить дрібнішою за масштаб
  const half = z > 1 ? R / z : R * 1.034;
  const lim = (v) => Math.max(-(R - half), Math.min(R - half, v));
  const [vx, vy] = z > 1 ? (o.mode === 'range' ? [lim(cx), lim(top + H / 2)] : o.hit ? [lim((Math.min(0, o.hx - o.hit[0], o.hit[0]) + Math.max(0, o.hx - o.hit[0], o.hit[0])) * k / 2), lim((Math.min(0, o.hy - o.hit[1], o.hit[1]) + Math.max(0, o.hy - o.hit[1], o.hit[1])) * k / 2)] : [lim(o.hx * k), lim(o.hy * k)]) : [0, 0];
  svg.setAttribute('viewBox', [vx - half, vy - half, 2 * half, 2 * half].join(' '));
  mk('rect', { x: -R, y: top + H, width: 2 * R, height: 2 * R, class: 'r-gr' }, g);
  const tg = mk('g', { transform: `translate(${cx} ${top}) scale(${o.flip ? -H : H} ${H})` }, g);
  if (!o.noTarget) mk('path', { d: T.path, class: 'r-tgt' }, tg);
  if (o.noTarget) tg.remove();
  else if (T.dark) mk('path', { d: T.dark, class: 'r-tgt-d' }, tg);
  if (!o.noTarget) (T.parts ?? []).forEach(([x, y, r, d]) => mk('circle', { cx: x, cy: y, r, class: d ? 'r-tgt-d' : 'r-tgt' }, tg));
  if (o.move && !o.noTarget) {
    // Стрілка руху над ціллю — куди вона йде так, як її видно в прицілі
    const len = Math.max(H * Math.max(T.w, 0.5) * 0.6, (R * 0.12) / z); const ay = top - (R * 0.04) / z; const x0 = cx - (o.move * len) / 2; const x1 = cx + (o.move * len) / 2;
    const hd = (R * 0.025) / z;
    mk('path', { d: `M${x0} ${ay}H${x1}M${x1 - o.move * hd * 1.6} ${ay - hd}L${x1} ${ay}L${x1 - o.move * hd * 1.6} ${ay + hd}`, class: 'r-move', 'stroke-width': (R * 0.012) / z }, g);
  }
  if (o.hide) mk('rect', { x: -R, y: top + H * (1 - o.hide), width: 2 * R, height: 2 * R, class: 'r-gr' }, g);
  if (o.zone && !o.noTarget) {
    // Зона влучання на цілі — коло навколо точки прицілювання радіусом «точно» з підсумку вправи; під сіткою, як «яблучко» на мішені
    mk('circle', { cx: o.hx * k, cy: o.hy * k, r: o.zone * k, class: 'r-zone', 'stroke-width': (R * 0.011) / z, 'stroke-dasharray': `${(R * 0.02) / z} ${(R * 0.014) / z}` }, g);
  }
  C.draw(g, R);
  if (o.mode === 'aim' && !o.noHold && (Math.abs(o.hx) > 0.05 || Math.abs(o.hy) > 0.05)) {
    // Кільце там, що ставиться на ціль, і підпис виносу поруч — щоб «де тримати» було видно на самій сітці
    const x = o.hx * k; const y = o.hy * k; const r = R * 0.045 / z;
    mk('circle', { cx: x, cy: y, r, class: 'r-hold', 'stroke-width': R * 0.012 / z }, g);
    // Стрілки — куди виносити приціл (мітка ліворуч від центру = брати правіше), а не де стоїть мітка на сітці
    const parts = [Math.abs(o.hy) > 0.05 ? `${o.hy > 0 ? '↑' : '↓'}${f(Math.abs(y), C.u === 'MOA' ? 1 : 2)}` : null,
      Math.abs(o.hx) > 0.05 ? `${o.hx > 0 ? '←' : '→'}${f(Math.abs(x), C.u === 'MOA' ? 1 : 2)}` : null].filter(Boolean);
    const right = x < (R / z) * 0.45;
    const label = mk('text', {
      x: right ? x + r * 1.5 : x - r * 1.5, y: y + (R * 0.033) / z, 'text-anchor': right ? 'start' : 'end',
      style: `font:700 ${(R * 0.095) / z}px system-ui,sans-serif;fill:var(--shoot);paint-order:stroke;stroke:var(--surface);stroke-width:${(R * 0.03) / z}px`,
    }, g);
    label.textContent = `${parts.join(' ')} ${C.u}`;
  }
  if (o.hit) {
    // «Винос» після відповіді: ✕ — куди пішла куля (мітка виносу), зелене кільце — куди мав дивитись центр (ціль мінус винос)
    const [px, py] = o.hit.map((v) => v * k); const a = (R * 0.02) / z;
    mk('circle', { cx: (o.hx - o.hit[0]) * k, cy: (o.hy - o.hit[1]) * k, r: (R * 0.045) / z, class: 'r-ok', 'stroke-width': (R * 0.014) / z }, g);
    mk('path', { d: `M${px - a} ${py - a}L${px + a} ${py + a}M${px - a} ${py + a}L${px + a} ${py - a}`, class: 'r-hit', 'stroke-width': (R * 0.012) / z }, g);
  }
  mk('circle', { cx: 0, cy: 0, r: R, class: 'r-l', 'stroke-width': R * 0.02 }, svg);
}

function mini(host, o, cap) {
  const fig = document.createElement('figure');
  const s = mk('svg', { class: 'ret', role: 'img', 'aria-label': cap.replace(/<[^>]+>/g, ' ') });
  fig.append(s);
  scope(s, o);
  const c = document.createElement('figcaption');
  c.innerHTML = cap;
  fig.append(c);
  host.append(fig);
}

/** Великі сітки з розмірами та галереї «як виглядає ціль на N м». */
export function initReticles(root) {
  const $ = (id) => root.querySelector(`#${id}`);
  if ($('dsmr-big')) dsmr($('dsmr-big'), 29.5);
  if ($('bplex-big')) bplex($('bplex-big'), 46);
  const gal = $('range-gallery');
  if (gal) {
    [100, 200, 300, 400, 500, 600].forEach((d) => mini(gal, { ret: 'dsmr', mag: 6, dist: d, tgt: 'man', mode: 'range' },
      `<b>${d} ${t('м')}</b>${t('рост {v} MRAD', { v: f(1700 / d, 1) })}`));
  }
  const pair = $('sfp-pair');
  if (pair) {
    mini(pair, { ret: 'dsmr', mag: 6, dist: 300, tgt: 'man', mode: 'range' }, `<b>${t('300 м на 6×')}</b>${t('5,7 деления = 5,7 MRAD')}`);
    mini(pair, { ret: 'dsmr', mag: 3, dist: 300, tgt: 'man', mode: 'range' }, `<b>${t('300 м на 3×')}</b>${t('2,8 деления, но это те же 5,7 MRAD')}`);
  }
  const bgal = $('bplex-gallery');
  if (bgal) {
    [200, 300, 400, 500, 600, 700].forEach((d) => mini(bgal, { ret: 'bplex', mag: 7, dist: d, tgt: 'man', mode: 'range' },
      `<b>${d} ${t('м')}</b>${t('рост {v} MOA', { v: f(170 * 34.377 / d, 1) })}`));
  }
}

